NEW_FILES = {'test_marker_room_routes.py': '"""A room holding an objective or loot marker keeps its dressing off its routes (0.251.0, the factory\'s roadmap 288).\n\nThe factory\'s census of what furnishing costs a route (`docs/findings/furnish_route_cost/` at the factory root), given\nan arm that strips only furnish\'s dressing -- the walker\'s guide\'s own measure, dressing over the functional build --\nfound eight routes over the library that the dressing made more than 10 % longer, seven of them one route in an\nobjective room, its door to its marker: one to four carton piles, pallets or dust sheets in rooms of 97 to 240 m2 that\nstand 3 to 7 % under furniture. `reserves_routes` now says what keeps off a room\'s routes -- "all" on a corner store\'s\nfloor (0.250.0), "dressing" in a room holding a marker -- and the shelter pass keeps its piece off them where it can.\nMeasured over the 50 specs that moved: the dressing\'s detours over 10 % 7 -> 0, the routes it narrows to single file\n37 -> 5. Refuted, kept: every floor piece kept off a marker room\'s routes -- 47 rooms, 45 already under the walker\'s\n12 % band, lost 45 pieces, and twin_a01\'s front_right_1 both of its own and the shelter they gave; and the shelter\npiece kept strictly off them -- the pawn_shop preset\'s safe_room lost its shelter.\n"""\nimport copy\nimport glob\nimport json\nimport os\nimport sys\n\nsys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))\n\nimport level_design as L  # noqa: E402\nimport migrate_furnish_recipes as M  # noqa: E402\n\nHERE = os.path.dirname(os.path.abspath(__file__))\n\n\ndef _load(name):\n    return json.load(open(os.path.join(HERE, "specs", name + ".json"), encoding="utf-8"))\n\n\ndef _library():\n    for p in sorted(glob.glob(os.path.join(HERE, "specs", "*.json"))):\n        if os.path.basename(p).startswith("lf_"):\n            continue\n        d = json.load(open(p, encoding="utf-8"))\n        if d.get("rooms"):\n            yield os.path.basename(p)[:-5], d\n\n\ndef _holds_marker(d, room):\n    """Asked through the endpoints a route is found between, which 0.250.0 has too."""\n    return any(kind in ("objective", "loot") for kind, _l, _x, _y in L.room_route_endpoints(d, room))\n\n\ndef _dressing_stems(room, building):\n    """A stem furnish places only as a cluster in this room\'s kind -- what the census calls dressing."""\n    kind = L._room_kind(room, building)\n    recipe = L._RECIPES[kind]\n    pools = list(recipe.get("clusters") or ())\n    if room.get("story", 0) < 0 and kind not in ("basement", "vault", "corridor", "wine_cellar"):\n        pools.append(L._BASEMENT_CLUSTER)\n    clustered = {s for pool, _lo, _hi in pools for s in pool}\n    functional = set()\n    for key in ("anchors", "wall", "floor", "fixtures"):\n        functional |= set(recipe.get(key) or ())\n    return clustered - functional\n\n\ndef test_a_room_says_what_keeps_off_its_routes():\n    """Every floor piece off a corner store\'s routes, the clusters off a marker room\'s, nothing reserved elsewhere."""\n    d = _load("deli_a03")\n    b = L.club_building_id(d)\n    rooms = {r["id"]: r for r in d["rooms"]}\n    assert L.reserves_routes(d, rooms["market_aisles"], b) == "all"\n    assert L.reserves_routes(d, rooms["apartment_hideout"], b) == "dressing"\n    assert L.holds_route_marker(d, rooms["apartment_hideout"])\n    plain = [r for r in d["rooms"] if not _holds_marker(d, r) and not L.is_corner_store_floor(r, b)]\n    assert plain and all(L.reserves_routes(d, r, b) == "" for r in plain), [r["id"] for r in plain]\n\n\ndef test_no_dressing_stands_on_a_marker_rooms_routes():\n    """THE LIBRARY AS SHIPPED. In every room holding an objective or loot marker, no piece of furnish\'s dressing stands\n    within half `two_abreast_width()` of a route the room reserves, allowing the half centimetre a written position may\n    move. On 0.250.0 the census\'s seven dressing detours stood exactly there."""\n    on, checked = [], 0\n    for name, d in _library():\n        b = L.club_building_id(d)\n        bare = L.unfurnished(copy.deepcopy(d))\n        for room in d["rooms"]:\n            if not _holds_marker(d, room) or L.is_corner_store_floor(room, b):\n                continue\n            stems, tag = _dressing_stems(room, b), L._room_tag(room)\n            mine = []\n            for v in d["volumes"]:\n                m = M._GENERATED.match(v["name"])\n                if m and m.group("tag") == tag and m.group("stem") in stems:\n                    mine.append(v)\n            if not mine:\n                continue\n            routes = L.protected_routes(bare, room)\n            checked += len(mine)\n            on += [(name, v["name"]) for v in mine\n                   if L.on_protected_route(routes, v["x"], v["y"], v["size_x"] - 0.01, v["size_y"] - 0.01)]\n    assert checked, "no dressing found in any marker room: the test asks nothing"\n    assert not on, on[:20]\n\n\ndef _stripped_room(name, rid):\n    """A spec with one room stripped of furnish\'s pieces and the shelter pass\'s, so the room needs shelter whatever\n    version furnished it."""\n    d0 = _load(name)\n    room = next(r for r in d0["rooms"] if r["id"] == rid)\n    tag = L._room_tag(room)\n    d0["volumes"] = [v for v in d0["volumes"] if not v["name"].endswith("_" + rid + "_shelter")\n                     and not (M._GENERATED.match(v["name"]) and "_" + tag + "_" in v["name"])]\n    return d0, room\n\n\ndef _sheltered(d0, rid, routes, monkeypatch):\n    """The shelter pass run on a copy of `d0`, the room `rid` reserving `routes`; its shelter pieces."""\n    monkeypatch.setattr(L, "protected_routes", lambda spec, rm: routes if rm["id"] == rid else [])\n    d = copy.deepcopy(d0)\n    L.seed_cover(d)\n    return [v for v in d["volumes"] if v["name"].endswith("_" + rid + "_shelter")]\n\n\ndef _through(room, piece):\n    """A thin route (half 0.30 m) across the room through where `piece` stands."""\n    x0, _y0, x1, _y1 = room["bounds"]\n    return [([(x0, piece["y"]), (x1, piece["y"])], 0.30)]\n\n\ndef test_the_shelter_pass_keeps_off_a_rooms_routes_where_it_can(monkeypatch):\n    """`seed_cover`\'s shelter piece keeps off a room\'s reserved routes as furnish\'s pieces do. apartment_walkup_a02\'s\n    safe_flat, stripped: asked no route, the pass stands its crate stack at one spot; given a route through that spot,\n    it stands it elsewhere, off the route. On 0.250.0, which asks no route, the crate stands on it."""\n    d0, room = _stripped_room("apartment_walkup_a02", "safe_flat")\n    free = _sheltered(d0, "safe_flat", [], monkeypatch)\n    assert len(free) == 1, "asked no route the room is sheltered"\n    planted = _through(room, free[0])\n    moved = _sheltered(d0, "safe_flat", planted, monkeypatch)\n    assert len(moved) == 1, "a room keeps its shelter"\n    v = moved[0]\n    assert not L.on_protected_route(planted, v["x"], v["y"], v["size_x"] - 0.01, v["size_y"] - 0.01), v\n\n\ndef test_a_room_with_no_spot_off_its_routes_keeps_its_shelter(monkeypatch):\n    """twin_a01\'s front_right_1 has one clear spot for a crate stack. With a route through it, the pass stands the\n    crate there rather than leave a room both sides see over everything in: kept strictly off its routes, the\n    pawn_shop preset\'s safe_room lost its shelter and `test_cover_breaks_sightlines` failed on it."""\n    d0, room = _stripped_room("twin_a01", "front_right_1")\n    free = _sheltered(d0, "front_right_1", [], monkeypatch)\n    assert len(free) == 1, "asked no route the room is sheltered"\n    kept = _sheltered(d0, "front_right_1", _through(room, free[0]), monkeypatch)\n    assert [(v["x"], v["y"]) for v in kept] == [(free[0]["x"], free[0]["y"])], kept\n\n\ndef test_the_library_is_sheltered_off_its_routes():\n    """Every shelter piece in a room that reserves its routes stands off them -- the pieces of earlier versions too,\n    which no pass moves."""\n    on = []\n    for name, d in _library():\n        b = L.club_building_id(d)\n        bare = None\n        for room in d["rooms"]:\n            if not (_holds_marker(d, room) or L.is_corner_store_floor(room, b)):\n                continue\n            mine = [v for v in d["volumes"] if v["name"].endswith("_" + room["id"] + "_shelter")]\n            if not mine:\n                continue\n            bare = bare or L.unfurnished(copy.deepcopy(d))\n            routes = L.protected_routes(bare, room)\n            on += [(name, v["name"]) for v in mine\n                   if L.on_protected_route(routes, v["x"], v["y"], v["size_x"] - 0.01, v["size_y"] - 0.01)]\n    assert not on, on\n'}
CHANGELOG = '## [0.251.0] - a room holding an objective or loot marker keeps its dressing off its routes\n\n**The factory\'s roadmap 288, and the note 289 left.** The factory\'s census of what furnishing costs a route\n(`docs/findings/furnish_route_cost/` at the factory root) has an arm, since 0.250.0 shipped, that strips only\nfurnish\'s dressing, so it reads the walker\'s guide\'s own measure: what the dressing costs a route over the functional\nbuild, flagged past 10 % (its section 14). Over the library at 0.250.0 eight routes were, and seven of them were one\nroute in an objective room, its door to its marker: funeral_home_a02\'s records_office 4.3 -> 5.5 m, courthouse_a02\'s\nrecords_room, apartment_walkup_a03\'s garage_cage and four more, each lengthened by one to four carton piles, pallets\nor dust sheets. The rooms are 97 to 240 m2 and stand 3.0 to 7.3 % under furniture; the route is short because the\nmarker stands near the door.\n\n### Changed\n- **`reserves_routes(spec, room, building)` says what keeps off a room\'s routes**: `"all"`, every floor piece furnish\n  stands -- a shop floor that stands rows, as 0.250.0 shipped it; `"dressing"`, its clusters only -- a room holding an\n  objective or loot marker (`holds_route_marker`, new), whatever its kind; `""`, nothing reserved. furnish asks it of\n  every room, not only a shop floor\'s; its rows, floor pieces and chairs keep off the routes where it says `"all"`,\n  its clusters wherever it says either.\n- **The shelter pass keeps off a room\'s reserved routes where it can.** `seed_cover` stands its shelter piece on a\n  clear spot off the routes the room reserves if one is, else on any clear spot as before: a crate stack in a route a\n  dressing pile was moved off would undo it, and a room must not lose its shelter for it. Its draws happen only on a\n  placement, so the second pass is 0.250.0\'s to the draw. A bare room\'s cover keeps off the routes outright.\n- **`agent_contract.json`\'s `sightlines` note** no longer says Lot carries the old 1.2 m crossing, which Lot has not\n  since roadmap 131: it names what derives the crossing now -- Lot\'s copies, held to Laser Tag\'s by Level Factory\'s\n  `check_sight_drift`, and Level Factory\'s advisory, from the body each run fields (Level Factory 0.230.0) -- and that\n  nothing in the factory carries 1.2 any more (searched first). No number in the file moved.\n- **The library refurnished and sheltered**: 51 rooms in 50 specs, every one holding a marker, and no other room (the\n  factory\'s `patches/dc_marker_routes/rooms_moved.out.txt`). Furnish\'s pieces 8,434 -> 8,428 and one shelter piece\n  more, twin_a01\'s front_right_1, standing off its route; a moved room\'s floor share -2.6 to +2.0 points, 50 of the 51\n  under the walker\'s 12 % before and after. The worst: clinic_a01\'s dispensary, about 5 -> 2.4 %, whose carton cluster\n  stands as one group and fits nowhere off its routes, and auto_shop_a01\'s parts_back 8.5 -> 6.9 %, a 26 x 5 m room\n  whose routes loop round most of its floor.\n\n### Measured, kept\n- **The census over the 50 specs**, 217 rooms and 1,000 pairs, 0.250.0 against this (the factory\'s\n  `patches/dc_marker_routes/census_changed.out.txt`, `pairs_compare.out.txt`): the dressing\'s detours over 10 % 7 in 7\n  rooms -> 0, the worst 1.270 -> 1.052, the routes it narrows to single file 37 -> 5; all of furnishing\'s over 10 % 18\n  in 16 rooms -> 12 in 11, the worst 1.270 -> 1.224; narrowed to single file 80 -> 51; two abreast after furnishing\n  742 -> 771; none closed. Pair by pair none crossed over 10 % in either measure, and the extra metres walked summed\n  over every pair 90.9 -> 87.0 for all of furnishing, 17.0 -> 9.9 for the dressing; 31 pairs regained two abreast, and\n  two lost it, both in market_hall_a01\'s deposit_cage, where working furniture now stands in the route.\n- **What dressing-only leaves.** Working furniture is not asked to keep off a marker room\'s routes, and where the\n  refurnish moved it there it stands: funeral_home_a02\'s records_office\'s door-to-marker route is 1.154 of its\n  authored length where it was 1.270, now for a desk. Plan views of four rooms before and after\n  (`patches/dc_marker_routes/plan_*.png`).\n- **The combat audit over the library** (`audit_compare.out.txt`): every code\'s count unchanged -- COVER_ALL_LOW 8,\n  OBJ_NARROW 10, OBJ_AT_DOOR 52 -- and two messages moved, a sightline 17.1 -> 17.0 m and landmark_hall_a01\'s\n  artifact_room counting five low pieces where it counted six.\n- REFUTED: every floor piece kept off a marker room\'s routes, as a corner store\'s are. 47 rooms moved, 45 of them\n  under the walker\'s 12 % already, and lost 45 pieces; twin_a01\'s front_right_1 lost both its pieces and the shelter\n  they gave, and the shelter pass, then asking no route, wanted a crate stack there.\n- REFUTED: the shelter piece kept strictly off the routes. The pawn_shop preset\'s safe_room had no clear spot left and\n  stood no shelter, its tallest piece 1.20 m against the 1.30 m crossing, and `test_cover_breaks_sightlines`\' two\n  corpus tests failed on it: a room both sides see over everything in cannot be fought in, and the walker\'s first ask\n  is the fight as much as the route.\n\n### Tests\n- **test_marker_room_routes.py** (new, 5): a room says what keeps off its routes; no dressing stands on a marker\n  room\'s routes, over the library; the shelter pass, given a route through the spot it would choose, stands its piece\n  elsewhere where there is an elsewhere (apartment_walkup_a02\'s safe_flat) and keeps it there where there is not\n  (twin_a01\'s front_right_1); the library\'s shelter pieces stand off the routes of the rooms that reserve them. On\n  0.250.0 two fail on behaviour -- dressing stands on marker rooms\' routes, the crate on the planted route -- one on\n  the new signature, and the two guards pass there.\n- **test_reserved_routes.py**: `test_a_floor_that_stands_rows_or_a_room_holding_a_marker_asks_for_its_routes`, which\n  was `test_only_a_floor_that_stands_rows_asks_for_its_routes`: furnishing office and deli_a03 asks for the market\n  aisles\' routes and those of the two rooms holding a marker, office\'s exec_suite and the deli\'s apartment_hideout. On\n  0.250.0 it fails on behaviour, the market aisles alone; the file\'s other five pass there (the factory\'s\n  `patches/dc_marker_routes/prove_tests_on_0250.out.txt`).\n\n'
OLD_VERSION, NEW_VERSION = 'Deli Counter 0.250.0', 'Deli Counter 0.251.0'


def _sha(b):
    return hashlib.sha256(b).hexdigest()[:16]


def _read(name):
    """The file's LF text and whether it is CRLF on disk; refuses mixed endings and a file that is not the pinned one."""
    raw = (REPO / name).read_bytes()
    crlf, lf = raw.count(b"\r\n"), raw.count(b"\n")
    if crlf not in (0, lf):
        raise SystemExit("REFUSED: deli_counter/%s has mixed line endings (%d CRLF of %d); nothing written"
                         % (name, crlf, lf))
    text = raw.decode("utf-8").replace("\r\n", "\n")
    if _sha(text.encode("utf-8")) != PINS[name]:
        raise SystemExit("REFUSED: deli_counter/%s is %s, not the %s this patch was written against; nothing "
                         "written" % (name, _sha(text.encode("utf-8")), PINS[name]))
    return text, crlf > 0


def main(argv):
    # every file worked out and checked before any is written
    out = {}
    for name, edits in EDITS.items():
        text, crlf = _read(name)
        for what, old, new in edits:
            if text.count(old) != 1:
                raise SystemExit("REFUSED: deli_counter/%s: the anchor at %s is there %d times; nothing written"
                                 % (name, what, text.count(old)))
            text = text.replace(old, new)
        out[name] = text.replace("\n", "\r\n") if crlf else text
    # a refurnished spec is carried whole, the file it replaces pinned like any other
    for name, text in REPLACED.items():
        _old, crlf = _read(name)
        out[name] = text.replace("\n", "\r\n") if crlf else text
    for name in NEW_FILES:
        if (REPO / name).exists():
            raise SystemExit("REFUSED: deli_counter/%s exists already; nothing written" % name)
    v = REPO / "VERSION"
    if v.read_bytes().decode("utf-8") != OLD_VERSION:
        raise SystemExit("REFUSED: VERSION reads %r, not %s; nothing written" % (v.read_text(), OLD_VERSION))
    cl = REPO / "CHANGELOG.md"
    craw = cl.read_bytes()
    if b"\r\n" in craw or not craw.startswith(b"## [" + OLD_VERSION.split()[-1].encode() + b"]"):
        raise SystemExit("REFUSED: CHANGELOG.md is not LF opening on %s; nothing written" % OLD_VERSION)
    for name, text in out.items():
        (REPO / name).write_bytes(text.encode("utf-8"))
    for name, text in NEW_FILES.items():
        (REPO / name).write_bytes(text.encode("utf-8"))
    v.write_bytes(NEW_VERSION.encode("utf-8"))
    cl.write_bytes(CHANGELOG.encode("utf-8") + craw)
    print("%s applied: %d files edited, %d written, VERSION, CHANGELOG. Now, in deli_counter/: build.py --all, "
          "suite" % (NEW_VERSION, len(out), len(NEW_FILES)))
    return 0


if __name__ == "__main__":
    sys.exit(main(sys.argv[1:]))
